import pandas as pd
import numpy as np
from datetime import timedelta

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    """
    Soft-delete CDC with sticky 7-day resurrection window.
    - Keep only new events (event_ts > watermark high_ts)
    - Apply events sequentially per user by (event_ts, event_seq)
    - 'D' ops: soft delete (status='DELETED', preserve email)
    - 'U' ops: upsert if ACTIVE/new, or resurrect only if > 7 days after deletion
    """

    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark_df = inputs["watermark"]

    # Extract watermark high_ts
    if watermark_df.empty:
        high_ts = pd.Timestamp.min
    else:
        high_ts = watermark_df["high_ts"].iloc[0]

    # Filter to only new events (strict inequality: event_ts > high_ts)
    new_events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Sort by user_id, then event_ts, then event_seq for deterministic processing
    new_events = new_events.sort_values(
        by=["user_id", "event_ts", "event_seq"],
        ascending=True
    ).reset_index(drop=True)

    # Initialize result as current snapshot
    result = target_snapshot.copy()

    # Build a dict of current state by user_id for efficient lookup/update
    state_dict = {}
    for _, row in result.iterrows():
        user_id = row["user_id"]
        state_dict[user_id] = {
            "email": row["email"],
            "status": row["status"],
            "status_ts": row["status_ts"]
        }

    # Process each event in order
    for _, event in new_events.iterrows():
        user_id = event["user_id"]
        event_ts = event["event_ts"]
        op = event["op"]
        email = event["email"]

        # Get current state for this user (default to ACTIVE if not in state_dict)
        if user_id in state_dict:
            current_state = state_dict[user_id]
        else:
            current_state = {
                "email": None,
                "status": "ACTIVE",
                "status_ts": pd.NaT
            }

        if op == 'D':
            # Soft delete: mark as DELETED, preserve email, update timestamp
            state_dict[user_id] = {
                "email": current_state["email"] if pd.notna(current_state["email"]) else email,
                "status": "DELETED",
                "status_ts": event_ts
            }

        elif op == 'U':
            # Update operation
            if current_state["status"] == "ACTIVE":
                # User is ACTIVE, so upsert normally
                state_dict[user_id] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": event_ts
                }
            elif current_state["status"] == "DELETED":
                # User is DELETED; check resurrection window (strict > 7 days)
                deletion_ts = current_state["status_ts"]

                # Strictly more than 7 days: event_ts > deletion_ts + 7 days
                if pd.notna(deletion_ts):
                    seven_days_later = deletion_ts + timedelta(days=7)
                    if event_ts > seven_days_later:
                        # Resurrect
                        state_dict[user_id] = {
                            "email": email,
                            "status": "ACTIVE",
                            "status_ts": event_ts
                        }
                    # else: within 7-day sticky window, discard the update
                else:
                    # Shouldn't happen (DELETED without status_ts), but handle gracefully
                    state_dict[user_id] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": event_ts
                    }
            else:
                # User doesn't exist yet or unknown status, treat as new/ACTIVE
                state_dict[user_id] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": event_ts
                }

    # Reconstruct the new snapshot from state_dict
    new_rows = []
    for user_id, state in state_dict.items():
        new_rows.append({
            "user_id": user_id,
            "email": state["email"],
            "status": state["status"],
            "status_ts": state["status_ts"]
        })

    if new_rows:
        new_snapshot = pd.DataFrame(new_rows)
    else:
        # If no rows, create empty DataFrame with correct schema
        new_snapshot = pd.DataFrame(columns=["user_id", "email", "status", "status_ts"])
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["email"] = new_snapshot["email"].astype("object")
        new_snapshot["status"] = new_snapshot["status"].astype("object")
        new_snapshot["status_ts"] = new_snapshot["status_ts"].astype("datetime64[us]")

    # Ensure correct dtypes
    new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
    new_snapshot["email"] = new_snapshot["email"].astype("object")
    new_snapshot["status"] = new_snapshot["status"].astype("object")
    new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"], utc=False).dt.as_unit("us")

    return {"new_snapshot": new_snapshot}
